// Data access layer: everything renders from validated static JSON indexes
// generated by scripts/generate_web_data.py from real .tooltrace bundles.
// No fabricated data: if an index is missing, pages show empty states.

export interface TaskSummary {
  id: string
  version: string
  category: string
  difficulty: string
  tags: string[]
  max_steps: number
  perturbations: string[]
}

export interface ResultRow {
  bundle: string
  task_id: string
  task_version: string
  agent: string
  success: boolean
  partial_success: boolean
  score_total: number
  steps: number
  tool_calls: number
  failed_tool_calls: number
  invalid_tool_calls: number
  repeated_calls: number
  unnecessary_changes: number
  workspace_violations: number
  wall_ms: number
  model_ms: number | null
  tool_ms: number
  failure_reason: string
  trust_state: string
  run_id: string
  created_at: string
}

export interface AgentRow {
  name: string
  runs: number
  success_rate: number
  mean_score: number
  mean_steps: number
  failed_tool_calls_mean: number
  wall_ms_p95: number
}

export interface IndexData {
  generated_at: string
  framework_version: string
  compatibility_key: string
  counts: { tasks: number; results: number; agents: number; packs: number }
}

async function fetchJson<T>(url: string): Promise<T> {
  const res = await fetch(url)
  if (!res.ok) throw new Error(`${url}: HTTP ${res.status}`)
  return (await res.json()) as T
}

export const getIndex = () => fetchJson<IndexData>('data/index.json')
export const getTasks = () => fetchJson<TaskSummary[]>('data/tasks.json')
export const getResults = () => fetchJson<ResultRow[]>('data/results.json')
export const getAgents = () => fetchJson<AgentRow[]>('data/agents.json')

import { useEffect, useState } from 'react'

export interface AsyncState<T> {
  data: T | null
  loading: boolean
  error: string | null
}

export function useAsync<T>(fn: () => Promise<T>, deps: unknown[] = []): AsyncState<T> {
  const [data, setData] = useState<T | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  useEffect(() => {
    let alive = true
    setLoading(true)
    setError(null)
    fn()
      .then((d) => {
        if (alive) setData(d)
      })
      .catch((e: unknown) => {
        if (alive) setError(e instanceof Error ? e.message : String(e))
      })
      .finally(() => {
        if (alive) setLoading(false)
      })
    return () => {
      alive = false
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)
  return { data, loading, error }
}
